package com.example.agroconnect.model; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="loan_documents") public class LoanDocument {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="loan_id") private Loan loan; private String originalFilename; private String storedFilename; private String contentType; private long fileSize; private String uploadedBy; private LocalDateTime uploadedAt=LocalDateTime.now(); public Long getId(){return id;} public Loan getLoan(){return loan;} public void setLoan(Loan v){loan=v;} public String getOriginalFilename(){return originalFilename;} public void setOriginalFilename(String v){originalFilename=v;} public String getStoredFilename(){return storedFilename;} public void setStoredFilename(String v){storedFilename=v;} public String getContentType(){return contentType;} public void setContentType(String v){contentType=v;} public long getFileSize(){return fileSize;} public void setFileSize(long v){fileSize=v;} public String getUploadedBy(){return uploadedBy;} public void setUploadedBy(String v){uploadedBy=v;} public LocalDateTime getUploadedAt(){return uploadedAt;}}
